package com.sawmillbaskethelper;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SawmillBasketHelperPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SawmillBasketHelperPlugin.class);
		RuneLite.main(args);
	}
}

package com.sawmillbaskethelper;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;
import org.apache.commons.lang3.ArrayUtils;

@PluginDescriptor(
	name = "Sawmill Basket Helper",
	description = "Left-click empties the log basket / forestry basket when near a sawmill operator",
	tags = {"sawmill", "log", "basket", "forestry", "empty", "menu", "swap", "woodcutting", "planks"}
)
public class SawmillBasketHelperPlugin extends Plugin
{
	// Log basket (closed/open) and Forestry basket (closed/open) item ids.
	private static final int[] BASKETS = {
		ItemID.LOG_BASKET_CLOSED,
		ItemID.LOG_BASKET_OPEN,
		ItemID.FORESTRY_BASKET_CLOSED,
		ItemID.FORESTRY_BASKET_OPEN
	};

	// Maximum distance (tiles) from a sawmill operator for the swap to apply.
	private static final int RADIUS = 4;

	// Matched case-insensitively against NPC names; covers every sawmill operator variant
	// (Varrock, Woodcutting Guild, Prifddinas, Auburnvale).
	private static final String OPERATOR_NAME = "sawmill operator";

	// Sawmill operators currently loaded in the scene, tracked via (de)spawn events so we
	// don't have to scan every NPC each frame.
	private final Set<NPC> operators = new HashSet<>();

	@Inject
	private Client client;

	@Inject
	private SawmillBasketHelperConfig config;

	@Override
	protected void startUp() throws Exception
	{
		seedOperators();
	}

	@Override
	protected void shutDown() throws Exception
	{
		operators.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// NPCs are despawned/respawned across scene loads and login; drop stale references.
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			operators.clear();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (isSawmillOperator(npc))
		{
			operators.add(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		operators.remove(event.getNpc());
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		// Runs after the client has built and sorted the menu (submenus are populated here),
		// so adding a top-level entry now makes it the left-click without being re-sorted away.
		if (!config.emptyBasket()
			|| client.getGameState() != GameState.LOGGED_IN
			|| client.isMenuOpen()
			|| client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		MenuEntry[] menuEntries = client.getMenuEntries();
		int topIdx = menuEntries.length - 1;
		if (topIdx < 0)
		{
			return;
		}

		MenuEntry top = menuEntries[topIdx];
		if (!ArrayUtils.contains(BASKETS, top.getItemId()))
		{
			return;
		}

		// Already the left-click option; nothing to do.
		if (Text.removeTags(top.getOption()).startsWith("Empty"))
		{
			return;
		}

		if (!nearSawmillOperator())
		{
			return;
		}

		// "Empty" is a subop nested under another op (e.g. "Check"), so it is not in the
		// top-level menu array. Find it inside a submenu and clone it to the top level.
		MenuEntry emptySubop = findEmptySubop(menuEntries);
		if (emptySubop != null)
		{
			promoteToLeftClick(emptySubop);
		}
	}

	private MenuEntry findEmptySubop(MenuEntry[] menuEntries)
	{
		for (MenuEntry entry : menuEntries)
		{
			Menu sub = entry.getSubMenu();
			if (sub == null)
			{
				continue;
			}
			for (MenuEntry subEntry : sub.getMenuEntries())
			{
				if (subEntry != null && Text.removeTags(subEntry.getOption()).startsWith("Empty"))
				{
					return subEntry;
				}
			}
		}
		return null;
	}

	private void promoteToLeftClick(MenuEntry subEntry)
	{
		// Subops can't be reparented to the top level, so clone the entry (mirrors RuneLite's
		// own Menu Entry Swapper). createMenuEntry(-1) inserts at the end of the array, which
		// is the top of the right-click menu and the default left-click target.
		client.createMenuEntry(-1)
			.setOption(subEntry.getOption())
			.setTarget(subEntry.getTarget())
			.setIdentifier(subEntry.getIdentifier())
			.setType(subEntry.getType() == MenuAction.CC_OP_LOW_PRIORITY ? MenuAction.CC_OP : subEntry.getType())
			.setItemId(subEntry.getItemId())
			.setParam0(subEntry.getParam0())
			.setParam1(subEntry.getParam1())
			.onClick(subEntry.onClick());
	}

	private boolean nearSawmillOperator()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}
		WorldPoint playerLoc = local.getWorldLocation();
		if (playerLoc == null)
		{
			return false;
		}

		for (NPC npc : operators)
		{
			WorldPoint npcLoc = npc.getWorldLocation();
			if (npcLoc != null && npcLoc.distanceTo(playerLoc) <= RADIUS)
			{
				return true;
			}
		}
		return false;
	}

	private void seedOperators()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		// One-time scan so operators already in the scene (e.g. when the plugin is toggled on
		// while standing at the sawmill) are tracked without waiting for a spawn event.
		for (NPC npc : client.getNpcs())
		{
			if (isSawmillOperator(npc))
			{
				operators.add(npc);
			}
		}
	}

	private static boolean isSawmillOperator(NPC npc)
	{
		return npc != null
			&& npc.getName() != null
			&& Text.removeTags(npc.getName()).toLowerCase().contains(OPERATOR_NAME);
	}

	@Provides
	SawmillBasketHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SawmillBasketHelperConfig.class);
	}
}

package com.sawmillbaskethelper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("sawmillbaskethelper")
public interface SawmillBasketHelperConfig extends Config
{
	@ConfigItem(
		keyName = "emptyBasket",
		name = "Empty basket near sawmill operator",
		description = "Left-click empties the log basket / forestry basket when near a sawmill operator"
	)
	default boolean emptyBasket()
	{
		return true;
	}
}
